import os,sys,json,base64,zipfile,io,subprocess,hashlib,time
from pathlib import Path
OUT=Path('/kaggle/working/faceid_validation');OUT.mkdir(exist_ok=True)
TMP=Path('/tmp/faceid_validation');TMP.mkdir(exist_ok=True)
os.environ['HF_HOME']=str(TMP/'hf');os.environ['UV_CACHE_DIR']=str(TMP/'uvcache')
os.environ['MPLBACKEND']='Agg'
zipfile.ZipFile(io.BytesIO(base64.b64decode(''))).extractall(TMP)
ROOT=TMP/'dramaforge';sys.path.insert(0,str(ROOT))
from forge.integrations.streaming_process import run_step
steps=[]
def cmd(args,cwd=None,timeout=1800):
 n='%02d'%len(steps)
 r=run_step(args,cwd=cwd,timeout_s=timeout,log_path=OUT/(n+'.log'),status_path=OUT/(n+'_status.json'))
 steps.append(r);(OUT/'steps.json').write_text(json.dumps(steps,indent=2))
 if r['status']!='passed':raise RuntimeError('step failed:'+n)
 return r
try:
 cmd([sys.executable,'-m','pip','install','uv'])
 uv=[sys.executable,'-m','uv']
 cmd(uv+['venv','--python','3.10',str(TMP/'env')])
 py=str(TMP/'env/bin/python')
 cmd(uv+['pip','install','--python',py,'torch==2.5.1','torchvision==0.20.1','--index-url','https://download.pytorch.org/whl/cu124'])
 cmd(uv+['pip','install','--python',py,'diffusers==0.25.1','transformers==4.37.2','huggingface-hub==0.25.2','accelerate==0.26.1','insightface==0.7.3','onnxruntime==1.20.1','numpy<2','opencv-python-headless<4.12','safetensors','sentencepiece','protobuf','Pillow','einops==0.8.2'])
 repo=ROOT/'third_party/ip_adapter_faceid';repo.parent.mkdir(exist_ok=True)
 cmd(['git','clone','https://github.com/tencent-ailab/IP-Adapter',str(repo)])
 cmd(['git','checkout','62e4af9d0c1ac7d5f8dd386a0ccf2211346af1a2'],cwd=repo)
 cmd([py,'-c', 'import sys;sys.path.insert(0,'+repr(str(repo))+');from ip_adapter.ip_adapter_faceid import IPAdapterFaceIDXL;print(123)'])
 (TMP/'download_weights.py').write_text("from pathlib import Path\nfrom huggingface_hub import snapshot_download,hf_hub_download\nfrom insightface.utils.storage import ensure_available\nTMP=Path('/tmp/faceid_validation')\nprint('STAGE_DOWNLOAD_SDXL',flush=True)\nsnapshot_download('stabilityai/stable-diffusion-xl-base-1.0',revision='462165984030d82259a11f4367a4eed129e94a7b',local_dir=str(TMP/'sdxl'),allow_patterns=['model_index.json','LICENSE.md','scheduler/*.json','tokenizer/*','tokenizer_2/*','text_encoder/config.json','text_encoder/model.safetensors','text_encoder_2/config.json','text_encoder_2/model.safetensors','unet/config.json','unet/diffusion_pytorch_model.safetensors','vae/config.json','vae/diffusion_pytorch_model.safetensors'])\nprint('STAGE_DOWNLOAD_FACEID',flush=True)\nhf_hub_download('h94/IP-Adapter-FaceID','ip-adapter-faceid_sdxl.bin',revision='43907e6f44d079bf1a9102d9a6e56aef7a219bae',local_dir=str(TMP/'adapter'))\nprint('STAGE_DOWNLOAD_BUFFALO',flush=True)\nensure_available('models','buffalo_l',root=str(TMP/'insightface'))\nprint('ALL_WEIGHTS_CACHED',flush=True)\n")
 cmd([py,str(TMP/'download_weights.py')],timeout=1800)
 (TMP/'execute_validation.py').write_text("import sys,json,hashlib\nfrom pathlib import Path\nTMP=Path('/tmp/faceid_validation');ROOT=TMP/'dramaforge';sys.path.insert(0,str(ROOT))\nfrom forge.gates.still_first import lock_stills\nfrom forge.integrations.faceid import prepare_faceid_batch,execute_faceid_batch\nOUT=Path('/kaggle/working/faceid_validation');project=TMP/'validation_project';project.mkdir(exist_ok=True)\nref=TMP/'reference.jpg';lock_stills(project,{'character:harry:approved':str(ref)})\nprompts={'front':'Cinematic photoreal closeup front view of this same adult wizard, round glasses, messy black hair, green eyes, same distinguishing facial features. Charcoal wizard robes, scarlet lining and gold trim, small lion crest, loosened white collar. Warm amber stone corridor. Natural skin texture, no text.', 'threequarter':'Cinematic photoreal closeup three-quarter view looking slightly left of this same adult wizard, round glasses, messy black hair, green eyes, same distinguishing facial features. Charcoal wizard robes, scarlet lining and gold trim, small lion crest, loosened white collar. Warm amber stone corridor. Natural skin texture, no text.'}\nbatch=prepare_faceid_batch(reference=ref,prompts=prompts,output_dir=OUT/'images',seed=42,width=512,height=768,steps=20)\n(OUT/'prepared_batch.json').write_text(json.dumps(batch,indent=2))\nprint('STAGE_REAL_EXECUTOR',flush=True)\nr=execute_faceid_batch(batch,project_dir=project,root=ROOT,base_model_dir=TMP/'sdxl',adapter_checkpoint=TMP/'adapter/ip-adapter-faceid_sdxl.bin',insightface_root=TMP/'insightface',personal_research_reviewed=True,python=sys.executable,timeout_s=1200)\n(OUT/'executor_result.json').write_text(json.dumps(r,indent=2))\nif not r['ok']:raise RuntimeError('FaceID executor failed')\nprint('ACTUAL_FACEID_EXECUTOR_OUTPUT_UNREVIEWED',flush=True)\n")
 cmd([py,str(TMP/'execute_validation.py')],timeout=1800)
 (OUT/'status.json').write_text(json.dumps({'status':'model_executor_passed_output_review_required','next':'download and inspect actual pixels'},indent=2))
except Exception as e:
 (OUT/'status.json').write_text(json.dumps({'status':'blocked','error':str(e)},indent=2));raise
